// --- reevaluate_rule (BACKLOG.md V3) ---

// reevaluateRuleArgs is reevaluate_rule's input: which loaded rule to run,
// and which specific object to run it against. GVK is deliberately NOT part
// of this — it comes from the rule itself (rule.GVK), so a caller cannot ask
// this tool to run rule X against an object of the wrong kind by mistake.
type reevaluateRuleArgs struct {
	RuleID    string `json:"ruleId"`
	Namespace string `json:"namespace,omitempty"`
	Name      string `json:"name"`
}

// reevaluateRuleResult is this tool's entire answer. Deliberately NOT the
// object, and not even the rule's full ruleTemplateData — this is a
// synthetic health check, not a second describe_resource, so it reports only
// what the caller (ValidationSweeper, via internal/api's AppliedValueVerifier
// implementation) actually needs to decide Resolved vs. Reopened.
type reevaluateRuleResult struct {
	// Found is false when the named object no longer exists at all — a
	// meaningfully different answer from Fires=false ("it exists and the
	// condition no longer holds"), which the caller renders as a different
	// sentence: an incident whose object was deleted was not necessarily
	// FIXED, just removed.
	Found bool `json:"found"`
	// Fires is whether the rule's condition matches the live object right
	// now. Only meaningful when Found is true.
	Fires bool `json:"fires"`
	// Message is the rule's own rendered Message when Fires is true (the
	// same text a fresh Finding would carry) — empty otherwise.
	Message string `json:"message,omitempty"`
}

// reevaluateRule is the agent-side half of BACKLOG.md V3's synthetic
// post-fix health check: given a rule ID and the object an incident named,
// answer whether that rule's condition STILL holds against live state,
// right now — not "did anything recur", the actual re-run of the check that
// opened the incident in the first place.
//
// This is read-only (list/get against whatever GVK the rule already names,
// both already covered by argus-investigate's RBAC — see validateRule's own
// supportedGVKs check, enforced again here for free by resourceInterface),
// so it needs none of scale_deployment/restart_pod's remediation gating.
//
// Deliberately reuses evaluateRule rather than re-implementing its
// condition logic against a single Get: evaluateRule already IS "list this
// rule's GVK and evaluate the condition against every object", and asking
// it for one specific namespace/name is a filter on its output, not a
// different code path. The alternative — a Get-then-evaluateCondition
// helper — would be a second way to reach the exact same five comparators,
// which is exactly the kind of duplication this file's own package doc
// warns against for the rule engine as a whole.
//
// One extra direct Get happens ONLY on the non-firing path, to tell "the
// object still exists and the condition cleared" apart from "the object is
// gone" — evaluateRule's list-based output cannot distinguish those (an
// object that's been deleted just silently isn't in the list), and the two
// deserve different sentences from the caller (see reevaluateRuleResult.Found).
func (e *ToolExecutor) reevaluateRule(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args reevaluateRuleArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return nil, false, fmt.Errorf("invalid args: %w", err)
	}
	if args.RuleID == "" {
		return nil, false, errors.New("ruleId is required")
	}
	if args.Name == "" {
		return nil, false, errors.New("name is required")
	}

	rule, ok := findRule(e.rules, args.RuleID)
	if !ok {
		return nil, false, fmt.Errorf("no loaded rule with id %q — it may have been removed, renamed, or never existed in this agent's currently-loaded rule set", args.RuleID)
	}

	// An unpaginated watch-cache read (the zero sweepReadPlan), deliberately
	// not the sweep's memory-guarded plan: this is one interactive tool call
	// re-evaluating one rule for one named object on behalf of an
	// investigation, not a pass that holds a dozen cluster-wide lists at
	// once. It has the whole budget to itself, and refusing or paginating it
	// would trade a bound nobody needs here for latency in front of a
	// waiting model.
	candidates, err := evaluateRule(ctx, e.dynamic, e.typed, rule, time.Now(), sweepReadPlan{})
	if err != nil {
		return nil, false, err
	}
	for _, c := range candidates {
		if c.Namespace == args.Namespace && c.Name == args.Name {
			return mustMarshal(reevaluateRuleResult{Found: true, Fires: true, Message: c.Message}), false, nil
		}
	}

	// Not among the currently-firing candidates. Tell "exists but clear"
	// apart from "no longer exists" with one direct Get — see doc comment.
	gvk, err := parseGVKString(rule.GVK)
	if err != nil {
		// Unreachable in practice: validateRule already parsed this same
		// string when this rule was loaded. Handled rather than assumed,
		// same posture renderRuleMessage's own unreachable branch takes.
		return nil, false, fmt.Errorf("rule %s: %w", rule.ID, err)
	}
	res, ok := supportedGVKs[gvk]
	if !ok {
		// Also unreachable — validateRule checked this at load time too —
		// and also handled rather than assumed for the same reason.
		return nil, false, fmt.Errorf("rule %s: gvk %q is not in supportedGVKs", rule.ID, rule.GVK)
	}
	if err := requireNamespaceFor(res, args.Namespace); err != nil {
		return nil, false, err
	}
	if _, getErr := e.resourceInterface(res, args.Namespace).Get(ctx, args.Name, metav1.GetOptions{}); getErr != nil {
		if apierrors.IsNotFound(getErr) {
			return mustMarshal(reevaluateRuleResult{Found: false, Fires: false}), false, nil
		}
		return nil, false, sanitizeK8sErr(getErr)
	}
	return mustMarshal(reevaluateRuleResult{Found: true, Fires: false}), false, nil
}

// ownershipFromMetadata runs every label/annotation GitOps signal against one
// object's metadata, in the precedence order this file has always used —
// Argo, then Flux, then Fleet, then plain Helm LAST. Returns nil when none
// match.
//
// Extracted so the identical checks can run against the queried object AND
// against each of its ancestors (see getGitOpsOwnership's owner-chain walk).
// Before that, these checks existed once, inline, applied only to the queried
// object — which meant a Pod of an Argo-managed Deployment reported "none".
//
// The Helm-last ordering is load-bearing and is the reason this is one
// function rather than several: Argo, Flux and Fleet all deploy charts, so a
// managed object carries Helm's release annotations too, and answering "helm"
// would send an operator to `helm upgrade` when the real source of truth is
// Git and the controller will simply revert them.
// identityOf builds an objectIdentity from a fetched object and its GVK.
func identityOf(gvk schema.GroupVersionKind, obj *unstructured.Unstructured) objectIdentity {
	return objectIdentity{Kind: gvk.Kind, Group: gvk.Group, Namespace: obj.GetNamespace(), Name: obj.GetName()}
}

// objectIdentity is the GVK/namespace/name of the object a metadata map came
// from, needed for the Argo self-reference check.
type objectIdentity struct {
	Kind      string
	Group     string
	Namespace string
	Name      string
}

// trackingIDSelfReferences reports whether an Argo tracking-id names the object
// carrying it. Format: "<app>:<group>/<Kind>:<ns>/<name>", where the app half
// may itself be "<ns>/<app>" for apps-in-any-namespace. An id we cannot parse
// into the full 3-part form is treated as NOT self-referencing — fail closed,
// since the whole point is refusing an attribution we cannot verify.
func trackingIDSelfReferences(trackingID string, self objectIdentity) bool {
	parts := strings.Split(trackingID, ":")
	if len(parts) != 3 {
		return false
	}
	groupKind, nsName := parts[1], parts[2]
	gk := strings.SplitN(groupKind, "/", 2)
	var group, kind string
	if len(gk) == 2 {
		group, kind = gk[0], gk[1]
	} else {
		kind = gk[0] // core group is written with an empty group prefix
	}
	nn := strings.SplitN(nsName, "/", 2)
	var ns, name string
	if len(nn) == 2 {
		ns, name = nn[0], nn[1]
	} else {
		name = nn[0] // cluster-scoped
	}
	return group == self.Group && kind == self.Kind && ns == self.Namespace && name == self.Name
}

// ownershipFromMetadata runs the label/annotation signals against one object's
// metadata. self identifies that object (for the Argo self-reference check);
// corroborate, when non-nil, reports whether an Argo Application of a given
// name exists (for the weak label signal). A nil corroborate disables the label
// path rather than trusting it.
func ownershipFromMetadata(labels, annotations map[string]string, self objectIdentity, corroborate func(appName string) bool) *gitOpsOwnershipResult {
	// Argo's LABEL tracking variant. The key is app.kubernetes.io/instance —
	// not argocd.argoproj.io/instance, which this checked until a real Argo CD
	// install was inspected and found never to write it (WORKLOG §125). But
	// DESIGN.md §11.2 is explicit that this label is "unreliable alone",
	// because **Helm charts conventionally set the same label to the release
	// name**. Treating it as proof of Argo ownership would misattribute every
	// Helm-managed object in a chart that follows the common labelling
	// convention — and post-PR-generation, a misattribution means a pull
	// request against the wrong repository.
	//
	// So it is a weak signal requiring corroboration: accepted only if an Argo
	// Application of that name actually exists. Uncorroborated, it falls
	// through to the Flux/Fleet/Helm checks below, where a Helm-labelled
	// object correctly lands on "helm".
	if instance := labels["app.kubernetes.io/instance"]; instance != "" && corroborate != nil && corroborate(instance) {
		return &gitOpsOwnershipResult{
			ManagedBy: "argocd",
			AppRef:    &gitOpsAppRef{Kind: "Application", Name: instance, InstallationID: annotations["argocd.argoproj.io/installation-id"]},
		}
	}
	// Argo CD's actual default tracking method (DESIGN.md §11.2 step 1) is
	// this annotation, not the instance label — confirmed live against a real
	// Argo install, whose Deployment carried the annotation and no labels at
	// all.
	// Argo's default ANNOTATION tracking, and the self-reference check
	// DESIGN.md §11.2 calls a "critical subtlety". Argo itself treats a
	// tracking-id that does not name the object carrying it as NOT managed —
	// that is its defence against resource-adoption attacks — so we must too.
	//
	// This was deliberately deferred when written, on the reasoning that no
	// GitOps controller was deployed anywhere yet. That reasoning expired: Argo
	// CD is now installed on the test cluster and PR generation is being built
	// on top of this attribution. An annotation copied onto an unrelated object
	// (by an attacker, or just by someone copy-pasting a manifest) would
	// otherwise attribute that object to another team's Application, and the
	// consequence is no longer a wrong label — it is a pull request opened
	// against the wrong repository.
	//
	// NOTE the subtlety for the ancestor walk: self must be the object whose
	// metadata this is, NOT the originally-queried object. When a Pod's
	// ownership is resolved from its Deployment's annotation, that annotation
	// self-references the Deployment. Checking it against the Pod would reject
	// every legitimate case.
	if ref := parseArgoTrackingID(annotations["argocd.argoproj.io/tracking-id"]); ref != nil {
		if trackingIDSelfReferences(annotations["argocd.argoproj.io/tracking-id"], self) {
			ref.InstallationID = annotations["argocd.argoproj.io/installation-id"]
			return &gitOpsOwnershipResult{ManagedBy: "argocd", AppRef: ref}
		}
		logger.Warn("get_gitops_ownership: ignoring a non-self-referencing Argo tracking-id; Argo treats these as unmanaged (resource-adoption defence), so attributing it would risk a PR against the wrong repository",
			slog.String("tracking_id", annotations["argocd.argoproj.io/tracking-id"]), slog.String("kind", self.Kind), slog.String("namespace", self.Namespace), slog.String("name", self.Name))
	}
	for _, group := range []struct{ prefix, kind string }{
		{"kustomize.toolkit.fluxcd.io", "Kustomization"},
		{"helm.toolkit.fluxcd.io", "HelmRelease"},
	} {
		// Annotations first, then labels: some Flux versions surface the same
		// name/namespace pair as labels, so detection is not version-specific
		// about which metadata kind it reads.
		if ref := fluxAnnotationRef(annotations, group.prefix, group.kind); ref != nil {
			return &gitOpsOwnershipResult{ManagedBy: "flux", AppRef: ref}
		}
		if ref := fluxAnnotationRef(labels, group.prefix, group.kind); ref != nil {
			return &gitOpsOwnershipResult{ManagedBy: "flux", AppRef: ref}
		}
	}
	// Rancher Fleet (BACKLOG.md F10). bundle-name is what Fleet stamps on
	// everything it deploys; the Bundle it names is the hop to the GitRepo
	// carrying the actual repo URL (repoFromFleetBundle).
	if bundle := labels["fleet.cattle.io/bundle-name"]; bundle != "" {
		ref := &gitOpsAppRef{Kind: "Bundle", Name: bundle}
		if ns := labels["fleet.cattle.io/bundle-namespace"]; ns != "" {
			ref.Namespace = ns
		}
		return &gitOpsOwnershipResult{ManagedBy: "fleet", AppRef: ref}
	}
	// meta.helm.sh/release-name is written by Helm v3 onto every object it
	// owns, and is what `helm` itself reads to decide ownership. Deliberately
	// NOT app.kubernetes.io/managed-by: Helm — that is a convention any chart
	// rendered through `helm template | kubectl apply` also carries, where no
	// release exists and nothing will ever revert anything, so it would
	// produce confident warnings about a reconcile that cannot happen.
	if release := annotations["meta.helm.sh/release-name"]; release != "" {
		ref := &gitOpsAppRef{Kind: "Release", Name: release}
		// The release namespace is where `helm` will look, which is not
		// necessarily the object's own namespace.
		if ns := annotations["meta.helm.sh/release-namespace"]; ns != "" {
			ref.Namespace = ns
		}
		return &gitOpsOwnershipResult{ManagedBy: "helm", AppRef: ref}
	}
	return nil
}

// finishOwnership attaches the repo target to a detected ownership result and
// marshals it — the single exit point every detection branch in
// getGitOpsOwnership routes through, so repo resolution happens in one place
// rather than being duplicated (and forgotten) at ten return sites.
//
// Resolution failure is never an error: the ownership answer is already useful
// on its own, and it is what the gitOpsManaged guardrail actually consumes.
// A missing repo target means "we could not prove where the source is", which
// is the honest result for plain Helm (no in-cluster record exists at all) and
// for any case where the controller's own object could not be read.
func (e *ToolExecutor) finishOwnership(ctx context.Context, namespace string, truncated bool, res gitOpsOwnershipResult) (json.RawMessage, bool, error) {
	if repo := e.resolveRepoTarget(ctx, namespace, res); repo != nil {
		res.Repo = repo
	}
	return mustMarshal(res), truncated, nil
}

// resolveRepoTarget reads the owning controller's own object to find the repo
// URL, path and — where the controller reports one — the resolved commit.
// Returns nil rather than an error on every failure path, per finishOwnership.
//
// Deliberately not attempted for "helm": a plain Helm release records nothing
// about where its chart came from (only meta.helm.sh/release-name), so there is
// no object to read. That gap is what repository_bindings exists to fill by
// human configuration — see REMEDIATION_ROADMAP.md milestone 2.1.
func (e *ToolExecutor) resolveRepoTarget(ctx context.Context, objNamespace string, res gitOpsOwnershipResult) *gitOpsRepoTarget {
	if res.AppRef == nil {
		return nil
	}
	// The controller object usually lives in its own namespace, not the
	// managed object's — Argo CD Applications in argocd/, Fleet GitRepos in
	// fleet-default/. AppRef.Namespace carries it when the detecting branch
	// knew it; fall back to the object's namespace only when it did not.
	ns := res.AppRef.Namespace
	if ns == "" {
		ns = objNamespace
	}

	switch res.ManagedBy {
	case "argocd":
		return e.repoFromArgoApplication(ctx, ns, res.AppRef.Name, res.AppRef.InstallationID)
	case "fleet":
		return e.repoFromFleetBundle(ctx, ns, res.AppRef.Name)
	case "flux":
		return e.repoFromFluxKustomization(ctx, ns, res.AppRef)
	}
	return nil
}

// repoFromArgoApplication reads spec.source plus status.sync.revision from an
// Argo CD Application. status.sync.revision is the whole point: it is the
// commit Argo actually last synced, which is what lld/09 §4/§5 mean by a
// pinned revision and why they say never HEAD. spec.source.targetRevision is
// usually a branch name and is reported as unpinned.
func (e *ToolExecutor) repoFromArgoApplication(ctx context.Context, namespace, name, installationID string) *gitOpsRepoTarget {
	gvk := schema.GroupVersionKind{Group: "argoproj.io", Version: "v1alpha1", Kind: "Application"}
	obj := e.fetchGitOpsObject(ctx, gvk, namespace, name)
	if obj == nil {
		// Argo CD's tracking-id annotation is
		// "<app>:<group>/<Kind>:<ns>/<name>", where the ns/name pair is the
		// MANAGED OBJECT's — it never says which namespace the Application
		// itself lives in. So a direct Get in the workload's namespace misses
		// every normal install, where Applications sit in the Argo CD
		// namespace (conventionally "argocd") and the workloads they manage
		// sit elsewhere. Found live: ownership resolved to "argocd" correctly
		// but the repo lookup came back empty for exactly this reason
		// (WORKLOG §121).
		//
		// Falling back to a cluster-wide list-and-match by name rather than
		// hardcoding "argocd": the namespace is genuinely install-specific,
		// and the agent's read RBAC already covers applications cluster-wide.
		// installationID (BACKLOG.md F16 item 2) disambiguates when two
		// separate Argo installations each own a same-named Application in
		// different namespaces — see findArgoApplicationByName.
		obj = e.findArgoApplicationByName(ctx, gvk, name, installationID)
		if obj == nil {
			return nil
		}
		namespace = obj.GetNamespace()
	}
	repoURL, _, _ := unstructured.NestedString(obj.Object, "spec", "source", "repoURL")
	if repoURL == "" {
		return nil
	}
	t := &gitOpsRepoTarget{RepoURL: repoURL, ResolvedFrom: fmt.Sprintf("argoproj.io/Application %s/%s .spec.source", namespace, name)}
	t.Path, _, _ = unstructured.NestedString(obj.Object, "spec", "source", "path")
	t.Branch, _, _ = unstructured.NestedString(obj.Object, "spec", "source", "targetRevision")
	if synced, _, _ := unstructured.NestedString(obj.Object, "status", "sync", "revision"); synced != "" {
		t.Revision = synced
		t.RevisionPinned = true
		t.ResolvedFrom = fmt.Sprintf("argoproj.io/Application %s/%s .status.sync.revision", namespace, name)
	} else {
		// Nothing synced yet. The branch is all we have, and it is not a
		// revision — say so rather than let a caller treat it as one.
		t.Revision = t.Branch
	}

	// Applier (lld/08 §12.3): syncPolicy.automated's mere PRESENCE (even an
	// empty {}) already enables Argo's automatic sync — prune/selfHeal are
	// sub-options of an already-automated policy, not what turns it on, so
	// this checks presence of the key, not any particular sub-field.
	if _, found, _ := unstructured.NestedMap(obj.Object, "spec", "syncPolicy", "automated"); found {
		t.Applier = "gitopsController"
	} else {
		t.Applier = "none"
	}

	// SourceEditable: Argo's own rendering classification, already computed
	// server-side — see gitOpsRepoTarget.SourceEditable's doc comment for why
	// this is read verbatim rather than guessed from the path.
	if sourceType, _, _ := unstructured.NestedString(obj.Object, "status", "sourceType"); sourceType != "" {
		editable := sourceType == "Directory"
		t.SourceEditable = &editable
	}
	return t
}

// repoFromFleetBundle walks Fleet's two hops: the managed object names a
// Bundle, and the Bundle names the GitRepo that actually carries the repo
// URL. Fleet's GitRepo reports its resolved commit in status.commit.
func (e *ToolExecutor) repoFromFleetBundle(ctx context.Context, namespace, bundleName string) *gitOpsRepoTarget {
	bundleGVK := schema.GroupVersionKind{Group: "fleet.cattle.io", Version: "v1alpha1", Kind: "Bundle"}
	bundle := e.fetchGitOpsObject(ctx, bundleGVK, namespace, bundleName)
	if bundle == nil {
		return nil
	}
	// Fleet labels the Bundle with the GitRepo that produced it. Without
	// that label this is a Bundle created directly (a legitimate Fleet
	// pattern), which has no Git source to report.
	repoName := bundle.GetLabels()["fleet.cattle.io/repo-name"]
	if repoName == "" {
		return nil
	}
	gitRepoGVK := schema.GroupVersionKind{Group: "fleet.cattle.io", Version: "v1alpha1", Kind: "GitRepo"}
	gr := e.fetchGitOpsObject(ctx, gitRepoGVK, bundle.GetNamespace(), repoName)
	if gr == nil {
		return nil
	}
	repoURL, _, _ := unstructured.NestedString(gr.Object, "spec", "repo")
	if repoURL == "" {
		return nil
	}
	t := &gitOpsRepoTarget{RepoURL: repoURL, ResolvedFrom: fmt.Sprintf("fleet.cattle.io/GitRepo %s/%s", bundle.GetNamespace(), repoName)}
	t.Branch, _, _ = unstructured.NestedString(gr.Object, "spec", "branch")
	// Fleet allows several paths per GitRepo. Join rather than pick one — a
	// caller narrowing to a single file needs to know it was ambiguous.
	if paths, ok, _ := unstructured.NestedStringSlice(gr.Object, "spec", "paths"); ok {
		t.Path = strings.Join(paths, ",")
	}
	if commit, _, _ := unstructured.NestedString(gr.Object, "status", "commit"); commit != "" {
		t.Revision = commit
		t.RevisionPinned = true
		t.ResolvedFrom += " .status.commit"
	} else if rev, _, _ := unstructured.NestedString(gr.Object, "spec", "revision"); rev != "" {
		// spec.revision pins a tag/commit when the user set one; still not
		// a controller-confirmed sync, so not marked pinned.
		t.Revision = rev
	} else {
		t.Revision = t.Branch
	}
	return t
}

// repoFromFluxKustomization resolves a Flux Kustomization's sourceRef to its
// GitRepository and reads the URL from there. Only Kustomization is handled:
// a HelmRelease's chart source may be a HelmRepository (an OCI/HTTP chart
// registry, not Git at all), so it has no single Git answer and is left for
// milestone 2.4 rather than guessed at here.
func (e *ToolExecutor) repoFromFluxKustomization(ctx context.Context, namespace string, ref *gitOpsAppRef) *gitOpsRepoTarget {
	if ref.Kind != "Kustomization" {
		return nil
	}
	ksGVK := schema.GroupVersionKind{Group: "kustomize.toolkit.fluxcd.io", Version: "v1", Kind: "Kustomization"}
	ks := e.fetchGitOpsObject(ctx, ksGVK, namespace, ref.Name)
	if ks == nil {
		return nil
	}
	srcKind, _, _ := unstructured.NestedString(ks.Object, "spec", "sourceRef", "kind")
	srcName, _, _ := unstructured.NestedString(ks.Object, "spec", "sourceRef", "name")
	if srcKind != "GitRepository" || srcName == "" {
		return nil
	}
	srcNS, _, _ := unstructured.NestedString(ks.Object, "spec", "sourceRef", "namespace")
	if srcNS == "" {
		srcNS = ks.GetNamespace()
	}
	grGVK := schema.GroupVersionKind{Group: "source.toolkit.fluxcd.io", Version: "v1", Kind: "GitRepository"}
	gr := e.fetchGitOpsObject(ctx, grGVK, srcNS, srcName)
	if gr == nil {
		return nil
	}
	repoURL, _, _ := unstructured.NestedString(gr.Object, "spec", "url")
	if repoURL == "" {
		return nil
	}
	t := &gitOpsRepoTarget{RepoURL: repoURL, ResolvedFrom: fmt.Sprintf("source.toolkit.fluxcd.io/GitRepository %s/%s", srcNS, srcName)}
	t.Path, _, _ = unstructured.NestedString(ks.Object, "spec", "path")
	t.Branch, _, _ = unstructured.NestedString(gr.Object, "spec", "ref", "branch")
	// Flux reports "branch@sha1:<commit>" here. Keep the whole string —
	// it is what Flux itself considers applied, and splitting it to look
	// tidier would discard which branch that commit came from.
	if applied, _, _ := unstructured.NestedString(ks.Object, "status", "lastAppliedRevision"); applied != "" {
		t.Revision = applied
		t.RevisionPinned = strings.Contains(applied, ":")
		t.ResolvedFrom += fmt.Sprintf(" + Kustomization %s/%s .status.lastAppliedRevision", namespace, ref.Name)
	} else {
		t.Revision = t.Branch
	}

	// Applier (lld/08 §12.3): spec.suspend defaults to false/absent, which is
	// Flux's own "actively reconciling" state — the kustomize-controller
	// keeps applying on every interval unless suspended. No SourceEditable
	// signal exists for Flux the way Argo's status.sourceType does (a
	// Kustomization always builds via kustomize, but the files it builds
	// FROM can themselves be plain manifests with no kustomization.yaml of
	// their own) — left nil/unknown rather than guessed, per
	// gitOpsRepoTarget.SourceEditable's own doc comment.
	suspended, _, _ := unstructured.NestedBool(ks.Object, "spec", "suspend")
	if suspended {
		t.Applier = "none"
	} else {
		t.Applier = "gitopsController"
	}
	return t
}

// findArgoApplicationByName lists Applications across all namespaces and
// returns the one matching name, or nil. Used only as repoFromArgoApplication's
// fallback, because Argo's tracking-id annotation does not carry the
// Application's own namespace.
//
// Ambiguity is resolved by refusing rather than guessing: two Applications
// with the same name in different namespaces are legitimate in a multi-tenant
// Argo install, and picking one would silently attribute a workload to the
// wrong team's repo — which, once this feeds PR generation, would mean opening
// a PR against the wrong repository. Better to report ownership without a repo
// target than to report a confident wrong one.
//
// installationID (DESIGN.md §11.2, BACKLOG.md F16 item 2) is the one case
// this refusal can resolve rather than just report: two separate Argo CD
// installations in one cluster, each configured with a distinct
// --installation-id, can each legitimately own an Application named "web" in
// their own namespace — the tracking-id annotation names the app by NAME
// alone, so name matching can't tell them apart. When the managed object's
// own installation-id annotation is non-empty AND it narrows the candidates
// to exactly one Application that itself carries the same value, that one is
// used instead of refusing. Left empty (the overwhelmingly common
// single-instance case), behavior is exactly the prior refuse-on-ambiguity.
// Not live-verified against an actual multi-installation Argo CD cluster —
// this dev environment runs exactly one Argo instance — so this is built
// against DESIGN.md §11.2's text and Argo's own documented multi-instance
// annotation, not observed live behavior; flagged rather than silently
// assumed proven.
func (e *ToolExecutor) findArgoApplicationByName(ctx context.Context, gvk schema.GroupVersionKind, name, installationID string) *unstructured.Unstructured {
	res, ok := supportedGVKs[gvk]
	if !ok {
		return nil
	}
	list, err := e.dynamic.Resource(res.gvr).Namespace(metav1.NamespaceAll).List(ctx, metav1.ListOptions{})
	if err != nil {
		logger.WarnContext(ctx, "get_gitops_ownership: could not list Applications to locate application", slog.String("name", name), logging.Err(err))
		return nil
	}
	var matches []*unstructured.Unstructured
	for i := range list.Items {
		if list.Items[i].GetName() == name {
			matches = append(matches, &list.Items[i])
		}
	}
	switch len(matches) {
	case 0:
		return nil
	case 1:
		return matches[0]
	}
	if installationID != "" {
		var narrowed []*unstructured.Unstructured
		for _, m := range matches {
			if m.GetAnnotations()["argocd.argoproj.io/installation-id"] == installationID {
				narrowed = append(narrowed, m)
			}
		}
		if len(narrowed) == 1 {
			logger.InfoContext(ctx, "get_gitops_ownership: multiple Argo Applications by name, disambiguated by installation-id",
				slog.Int("matches", len(matches)), slog.String("name", name), slog.String("namespace", narrowed[0].GetNamespace()), slog.String("resolved_name", narrowed[0].GetName()), slog.String("installation_id", installationID))
			return narrowed[0]
		}
	}
	logger.WarnContext(ctx, "get_gitops_ownership: multiple Argo Applications named the same in different namespaces; refusing to guess which owns this object, so no repo target is reported", slog.Int("matches", len(matches)), slog.String("name", name))
	return nil
}

// fetchGitOpsObject is a Get that treats every failure as "not available"
// rather than an error — a missing CRD, an RBAC denial on a cluster where the
// Fleet grant was not applied, or a deleted Application are all normal and all
// mean the same thing to the caller. Logged, because a persistent RBAC denial
// is worth seeing in the agent log rather than silently degrading every
// ownership answer.
func (e *ToolExecutor) fetchGitOpsObject(ctx context.Context, gvk schema.GroupVersionKind, namespace, name string) *unstructured.Unstructured {
	res, ok := supportedGVKs[gvk]
	if !ok {
		return nil
	}
	obj, err := e.resourceInterface(res, namespace).Get(ctx, name, metav1.GetOptions{})
	if err != nil {
		logger.WarnContext(ctx, "get_gitops_ownership: could not read object for repo resolution", slog.String("kind", gvk.Kind), slog.String("namespace", namespace), slog.String("name", name), logging.Err(err))
		return nil
	}
	return obj
}

// findGitOpsOwnerNode scans an already-walked owner chain for the first
// node whose GVK's GroupKind is in the given set, returning it as an
// app_ref. Node.GVK is checked regardless of Node.Resolved — Application/
// ApplicationSet/Kustomization/HelmRelease are never in supportedGVKs, so
// ownerChainUpNodes always reports them Resolved: false (an unsupported
// Kind it never attempted to Get, not a broken reference) — that's expected
// here, not a reason to treat the owner as unfound.
func findGitOpsOwnerNode(nodes []ownerChainNode, kinds map[schema.GroupKind]bool) *gitOpsAppRef {
	for _, n := range nodes {
		gvk, err := parseGVKString(n.GVK)
		if err != nil {
			continue
		}
		if kinds[gvk.GroupKind()] {
			return &gitOpsAppRef{Kind: gvk.Kind, Namespace: n.Namespace, Name: n.Name}
		}
	}
	return nil
}

// parseArgoTrackingID parses the argocd.argoproj.io/tracking-id annotation's
// "<app>:<group>/<Kind>:<ns>/<name>" format (DESIGN.md
// §11.2 step 1), extracting just the leading "<app>" (or, for the
// apps-in-any-namespace variant, "<namespace>/<app>") segment. Returns nil
// for an empty or malformed value rather than a best-effort guess.
func parseArgoTrackingID(trackingID string) *gitOpsAppRef {
	if trackingID == "" {
		return nil
	}
	appID := strings.SplitN(trackingID, ":", 2)[0]
	if appID == "" {
		return nil
	}
	if idx := strings.Index(appID, "/"); idx >= 0 {
		return &gitOpsAppRef{Kind: "Application", Namespace: appID[:idx], Name: appID[idx+1:]}
	}
	return &gitOpsAppRef{Kind: "Application", Name: appID}
}

// fluxAnnotationRef reads the "<group>/name" (+ optional "<group>/
// namespace") metadata pair DESIGN.md §11.2 step 2 and this
// task's brief both name for Flux — same helper for either the annotations
// or the labels map (see the labels-fallback comment above), and for either
// the kustomize.toolkit.fluxcd.io or helm.toolkit.fluxcd.io group. Returns
// nil when the name half is absent; the namespace half is optional (some
// configurations omit it for a same-namespace resource).
func fluxAnnotationRef(metadata map[string]string, group, kind string) *gitOpsAppRef {
	name := metadata[group+"/name"]
	if name == "" {
		return nil
	}
	return &gitOpsAppRef{Kind: kind, Namespace: metadata[group+"/namespace"], Name: name}
}
